import { Dialog, DialogContent, DialogOverlay } from "./dialog";

interface ImageDialogProps {
  src: string;
  alt: string;
  open: boolean;
  onClose: () => void;
}

function ImageDialog({ src, alt, ...props }: ImageDialogProps) {
  const { open, onClose } = props;

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogOverlay className="bg-background/20 backdrop-blur-sm" />
      <DialogContent className="p-0 rounded-md w-full">
        <img className="rounded-lg w-full" src={src} alt={alt} />
      </DialogContent>
    </Dialog>
  );
}

export default ImageDialog;