import React, { useEffect, useMemo, useState } from 'react';
import ScrollToBottom from 'react-scroll-to-bottom';
import { useDispatch, useSelector } from 'react-redux';
import {
  setTaskID,
  setModelID,
  setFeedbackAction,
  setFeedbackStatus,
  setDescription,
  setSkillID,
  getSkillInfoAction
} from '@/store/module/chat/chatSlice';
import { RootState, AppDispatch } from '@/store';
import { Button } from '@/shadcn-ui/components/ui/button';
import { Separator } from '@/shadcn-ui/components/ui/separator';
import { Copy, MessageSquare, X } from 'lucide-react';
import { FaRegThumbsUp, FaThumbsUp, FaRegThumbsDown, FaThumbsDown } from "react-icons/fa6";
import './index.css';
import { ScrollArea } from '@/shadcn-ui/components/ui/scroll-area';
import { cn } from '@/shadcn-ui/lib/utils';
import tools from '@/utils/tools';
import { downloadFile } from '@/api/chatApi';
import { useTranslation } from 'react-i18next';
import Markdown, { ExtraProps } from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter'
import { vscDarkPlus } from 'react-syntax-highlighter/dist/esm/styles/prism'
import { Tooltip, TooltipProvider, TooltipContent, TooltipTrigger } from '@/shadcn-ui/components/ui/tooltip';
import { languageMap } from '@/utils/map';
import BadFeedbackForm from './BadFeedback';
import "highlight.js/styles/github.css";
import { toast } from '@/shadcn-ui/components/ui/use-toast';
import Hint from './Wellcome/hint';
import ChatWithDragDrop from './InputField';

export interface ChatProps {
  apiKey: string;
  baseUrl: string;
}

function Chat({ apiKey, baseUrl }: ChatProps) {
  const { t } = useTranslation('chat')
  const { t: commonT } = useTranslation('common')
  const { fileDownload, clipboard } = tools;
  const dispatch = useDispatch<AppDispatch>();
  const { skillInfo, chatId, messages, loadingAsk, description } = useSelector((state: RootState) => state.chat);

  useEffect(() => {
    initComponent();
  }, [])

  // useEffect(() => {
  //   if (id) {
  //     dispatch(setTaskID(id))
  //     dispatch(setSkillID(id))
  //   }

  //   return () => { }
  // }, [id, skillList])

  const initComponent = async () => {
    await dispatch(getSkillInfoAction({ baseUrl, apiKey }))
  }

  const checkSourceIsNone = (source: Array<{ name: string, id: string, page?: string }>) => {
    if (source.length === 0) return false
    if (source.some(item => !item.id)) return false
    return true
  }

  const download = async (id: string, name: string) => {
    if (!id) return
    const { data } = await downloadFile({ fileID: id }, baseUrl).catch(() => {
      toast({
        title: commonT('downloadError'),
        description: commonT('downloadErrorDesc'),
        variant: 'destructive',
        duration: 3000,
      })
    }) as { data: Blob }

    fileDownload(data, name)
  }

  const pageBadge = (page: string, maxLength?: number) => {
    const setPage = page.split(',').sort((a, b) => Number(a) - Number(b))
    const maxSetPage = maxLength ? setPage.length > maxLength ? setPage.slice(0, 3) : setPage : setPage
    const pageText = maxSetPage.join(', ')

    return <div className='flex gap-2 items-center'>
      <span>{pageText}</span>
    </div>
  }

  const truncate = (str: string, maxLength: number) => {
    if (!str) return ''
    if (str.length <= maxLength) {
      return str;
    }
    return str.slice(0, maxLength) + '...';
  };

  const codeBlock = (props: React.ClassAttributes<HTMLElement> & React.HTMLAttributes<HTMLElement> & ExtraProps) => {
    const { children, className, node, ...rest } = props
    const match = /language-(\w+)/.exec(className || '')

    const convertedLanguage = (code: string) => languageMap[code.toLowerCase() as keyof typeof languageMap] || code;

    return match ? (
      <div className='relative w-full border border-zinc-700 border-solid rounded-md bg-[#1e1e1e] flex flex-col'>
        <div className='h-9 flex items-center justify-between px-4 bg-zinc-700 border-b border-[#1e1e1e] border-solid rounded-t-md'>
          <div className='text-white text-lg font-semibold'>{convertedLanguage(match[1])}</div>
        </div>
        <div className='sticky top-9'>
          <div className='absolute end-0 bottom-0 flex h-9 items-center pe-2'>
            <div className="text-token-text-secondary flex items-center rounded-sm px-2 font-sans text-xs">
              <Button variant={'link'} size={'sm'} className="flex gap-1 items-center text-white text-xs px-0" onClick={() => clipboard(children)}>
                <Copy color='white' size={16} />
                {commonT('copy')}
              </Button>
            </div>
          </div>
        </div>
        <SyntaxHighlighter
          {...rest}
          PreTag="div"
          children={String(children).replace(/\n$/, '')}
          language={match[1]}
          style={vscDarkPlus}
          ref={node as React.LegacyRef<SyntaxHighlighter> | undefined}
        />
      </div>
    ) : (
      <code {...rest} className={className}>
        {children}
      </code>
    )
  }

  const [feedbackOpen, setFeedbackOpen] = React.useState(false);
  const [feedbackMessageID, setFeedbackMessageID] = React.useState(0);

  const setGood = async (messageID: number) => {
    if (!chatId || !messageID) return

    await dispatch(setFeedbackAction({ chatID: chatId, messageID, evaluation: 1, feedback: '', baseUrl }))
    dispatch(setFeedbackStatus({ messageID, evaluation: 1, feedback: '' }))
    toast({
      description: commonT("thankFeedback"),
      duration: 3000,
    })
  }

  const setBad = async (messageID: number, feedback: string) => {
    if (!chatId || !messageID) return

    await dispatch(setFeedbackAction({ chatID: chatId, messageID, evaluation: 2, feedback, baseUrl }))
    dispatch(setFeedbackStatus({ messageID, evaluation: 2, feedback }))
    toast({
      description: commonT("thankFeedback"),
      duration: 3000,
    })
  }

  const skillName = useMemo(() => {
    if (!skillInfo) return ''
    const skill = skillInfo
    return skill?.skillName || ''
  }, [skillInfo, apiKey])

  const [isOpen, setIsOpen] = useState(false)
  const toggleChat = () => {
    setIsOpen(!isOpen)
  }

  return (
    <>
      <Button
        onClick={toggleChat}
        className="fixed bottom-6 right-6 rounded-full w-14 h-14 shadow-lg z-50 p-0 flex items-center justify-center bg-black hover:bg-zinc-700"
      >
        {isOpen ? <X size={24} /> : <MessageSquare size={24} />}
      </Button>

      <div className={cn('bg-[#F0F5FE] w-full max-w-[450px] flex flex-col h-[600px]',
        "fixed bottom-24 right-6 rounded-lg shadow-xl z-40 transition-all duration-300 ease-in-out flex flex-col",
        "border border-gray-200",
        isOpen ? "opacity-100 translate-y-0" : "opacity-0 translate-y-8 pointer-events-none",
      )}>
        <div className="chat flex-1 basis-full overflow-hidden">
          <ScrollToBottom className='transition-colors h-full relative' followButtonClassName='' mode={"bottom"}>
            {
              messages.length === 0 && !chatId &&
              <div className='h-full mx-auto lg:max-w-[960px] md:max-w-[720px] sm:max-w-[600px]'>
                <Hint description={description} skillName={skillName} />
              </div>
            }
            {(messages.length > 0 || chatId) && <div id='talk' className='flex flex-col mx-auto lg:max-w-[960px] md:max-w-[720px] sm:max-w-[600px]'>
              {
                messages.map((item, index) => {
                  if (item.role === 'bot' && item.content) {
                    return (
                      <div
                        className={cn('flex gap-3 m-4 ml-6')}
                        key={index}
                      >
                        <div className='w-full text-black text-left bg-white shadow-md outline-none rounded-lg px-2 whitespace-wrap'>
                          <div className='p-2 py-4 markdown prose relative' >
                            <Markdown
                              remarkRehypeOptions={{ allowDangerousHtml: true }}
                              remarkPlugins={[remarkGfm]}
                              // rehypePlugins={[rehypeHighlight]}
                              components={{
                                hr: () => <Separator className='my-3 bg-gray-400' />,
                                code: codeBlock,
                                a: ({ node, ...props }) => <a {...props} target="_blank" rel="noreferrer" />,
                              }}
                            >
                              {item.content}
                            </Markdown>
                            {item.done && <div className='flex flex-wrap gap-2 mt-6'>
                              <TooltipProvider delayDuration={100} skipDelayDuration={100}>
                                <Tooltip>
                                  <TooltipTrigger asChild>
                                    <button
                                      className='flex flex-row items-center gap-1 rounded-md text-gray-600 p-1 py-0.5 text-xs transition-opacity delay-100 hover:bg-gray-100'
                                      onClick={() => clipboard(item.content)}
                                    >
                                      <Copy size={16} />
                                    </button>
                                  </TooltipTrigger>
                                  <TooltipContent>
                                    <div className="text-sm">{commonT('copy')}</div>
                                  </TooltipContent>
                                </Tooltip>
                              </TooltipProvider>

                              <TooltipProvider delayDuration={100} skipDelayDuration={100}>
                                <Tooltip>
                                  <TooltipTrigger asChild>
                                    <button
                                      className='flex flex-row items-center gap-1 rounded-md text-gray-600 p-1 py-0.5 text-xs transition-opacity delay-100 hover:bg-gray-100'
                                      onClick={() => setGood(item.id)}
                                    >
                                      {item.evaluation === 1 ? <FaThumbsUp size={16} /> : <FaRegThumbsUp size={16} />}
                                    </button>
                                  </TooltipTrigger>
                                  <TooltipContent>
                                    <div className="text-sm">{t("feedbackGood")}</div>
                                  </TooltipContent>
                                </Tooltip>
                              </TooltipProvider>

                              <TooltipProvider delayDuration={100} skipDelayDuration={100}>
                                <Tooltip>
                                  <TooltipTrigger asChild>
                                    <button
                                      className='flex flex-row items-center gap-1 rounded-md text-gray-600 p-1 py-0.5 text-xs transition-opacity delay-100 hover:bg-gray-100'
                                      onClick={() => {
                                        setFeedbackMessageID(item.id)
                                        setFeedbackOpen(true)
                                      }}
                                    >
                                      {item.evaluation === 2 ? <FaThumbsDown size={16} /> : <FaRegThumbsDown size={16} />}
                                    </button>
                                  </TooltipTrigger>
                                  <TooltipContent>
                                    <div className="text-sm">{t("feedbackBad")}</div>
                                  </TooltipContent>
                                </Tooltip>
                              </TooltipProvider>
                            </div>}
                          </div>
                          {item.source.length ? <Separator /> : null}
                          <ScrollArea className="w-full">
                            {item.source.length && checkSourceIsNone(item.source) ? <div className='text-sm px-3 pt-2'>{t('sources')} {'(' + t('clickToDownload') + ')'}</div> : null}
                            {item.source.length ? <div className="flex flex-col gap-1 p-2 w-full">
                              {item.source.map((source, idx) => (
                                <button
                                  key={idx}
                                  className={cn(
                                    "flex flex-col items-start gap-2 w-full p-2 text-left text-sm transition-all rounded-lg hover:bg-accent"
                                  )}
                                  disabled={!checkSourceIsNone(item.source)}
                                  onClick={() => download(source.id, source.name)}
                                >
                                  <div className="flex w-full flex-col gap-1">
                                    <div className="flex items-center justify-between">
                                      <div className="flex items-center">
                                        <TooltipProvider>
                                          <Tooltip>
                                            <TooltipTrigger asChild>
                                              {
                                                !checkSourceIsNone(item.source) ? <div className="font-semibold">{t('AISlogan')}</div>
                                                  :
                                                  <div className="font-semibold text-[#005e73] to-blue-700">{truncate(source.name, 15)}</div>
                                              }
                                            </TooltipTrigger>
                                            <TooltipContent>
                                              <div className="text-sm">{source.name}</div>
                                            </TooltipContent>
                                          </Tooltip>
                                        </TooltipProvider>
                                      </div>
                                      <TooltipProvider>
                                        <Tooltip>
                                          <TooltipTrigger asChild>
                                            {source.page && <span className="font-semibold flex gap-2 text-[#005e73]">{`Page.`}{pageBadge(source.page, 3)}</span>}
                                          </TooltipTrigger>
                                          <TooltipContent>
                                            {source.page && <span className="font-semibold flex gap-2 text-[#005e73]">
                                              {`Page.`}{pageBadge(source.page)}
                                            </span>
                                            }
                                          </TooltipContent>
                                        </Tooltip>
                                      </TooltipProvider>
                                    </div>
                                  </div>
                                </button>
                              ))}
                            </div>
                              : null}
                          </ScrollArea>
                        </div>
                      </div>
                    )
                  }

                  if (item.role === 'user' && item.content) {
                    return (
                      <div className='flex justify-end items-center m-4 gap-5' key={index}>
                        <div className='text-white text-left bg-[#82C000] shadow-md p-3 select-text rounded-lg break-words overflow-hidden'>
                          <div className='px-1 overflow-auto whitespace-pre-wrap break-words'>
                            {item.content}
                          </div>
                        </div>
                      </div>
                    )
                  }

                  return null
                })
              }
              {
                loadingAsk && <div className='flex items-center m-4 gap-5'>
                  <div className='relative text-black text-left outline-none rounded-lg w-24 h-16 break-words overflow-hidden'>
                    <div className='loader absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2'></div>
                  </div>
                </div>
              }
            </div>
            }
          </ScrollToBottom>
        </div >

        <div className='px-4 py-2 bg-[#F0F5FE]'>
          <div
            className={
              cn(
                "w-full bg-white shadow rounded-lg border-2 m-0 mx-auto lg:max-w-[960px] md:max-w-[720px] sm:max-w-[600px]"
              )
            }
          >
            <ChatWithDragDrop apiKey={apiKey} baseUrl={baseUrl} />
          </div>
        </div>
      </div >

      <BadFeedbackForm open={feedbackOpen} onOk={(content) => setBad(feedbackMessageID, content)} onClose={() => setFeedbackOpen(false)} />
    </>
  );
}

export default Chat;
