"use client"

import { useState, useEffect, useRef } from "react"
import { motion } from "framer-motion"
import { Mic, X } from "lucide-react"
import { Button } from "@/shadcn-ui/components/ui/button"
import SpeechRecognition, { useSpeechRecognition } from "react-speech-recognition"
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/shadcn-ui/components/ui/dialog"
import { useToast } from "@/shadcn-ui/components/ui/use-toast"

interface VoiceModalProps {
  isOpen: boolean
  onClose: (transcript: string) => void
}

export default function VoiceModal({ isOpen, onClose }: VoiceModalProps) {
  const [volume, setVolume] = useState(0)

  const audioContextRef = useRef<AudioContext | null>(null)
  const analyserRef = useRef<AnalyserNode | null>(null)
  const dataArrayRef = useRef<Uint8Array | null>(null)
  const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null)
  const animationFrameRef = useRef<number | null>(null)
  const streamRef = useRef<MediaStream | null>(null)
  const { toast } = useToast()

  // Use react-speech-recognition hook
  const { transcript, resetTranscript, browserSupportsSpeechRecognition, isMicrophoneAvailable } =
    useSpeechRecognition()

  // Start listening when the modal opens
  useEffect(() => {
    if (isOpen) {
      startListening()
    }
  }, [isOpen])

  const startListening = async () => {
    try {
      resetTranscript()

      // Start speech recognition with react-speech-recognition
      await SpeechRecognition.startListening({
        continuous: true,
        language: "zh-TW", // Set language to Traditional Chinese
      })

      // Get microphone stream for audio visualization
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true })
      streamRef.current = stream

      // Initialize audio context for visualization
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)()
      analyserRef.current = audioContextRef.current.createAnalyser()
      sourceRef.current = audioContextRef.current.createMediaStreamSource(stream)

      // Connect the source to the analyser
      sourceRef.current.connect(analyserRef.current)

      // Configure analyser
      analyserRef.current.fftSize = 256
      const bufferLength = analyserRef.current.frequencyBinCount
      dataArrayRef.current = new Uint8Array(bufferLength)

      updateVolume()
    } catch (error) {
      console.error("Error accessing microphone:", error)
    }
  }

  const stopListening = () => {
    // Stop speech recognition
    SpeechRecognition.stopListening()

    // Stop audio processing
    if (audioContextRef.current) {
      if (sourceRef.current) {
        sourceRef.current.disconnect()
        sourceRef.current = null
      }

      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current)
        animationFrameRef.current = null
      }

      audioContextRef.current.close()
      audioContextRef.current = null
      analyserRef.current = null
    }

    // Stop media stream
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => track.stop())
      streamRef.current = null
    }

    setVolume(0)
  }

  const handleClose = () => {
    stopListening()
    onClose(transcript)
    resetTranscript()
  }

  const updateVolume = () => {
    if (!analyserRef.current || !dataArrayRef.current) return

    analyserRef.current.getByteFrequencyData(dataArrayRef.current)

    // Calculate average volume
    let sum = 0
    for (let i = 0; i < dataArrayRef.current.length; i++) {
      sum += dataArrayRef.current[i]
    }
    const avg = sum / dataArrayRef.current.length

    // Normalize to 0-1 range and apply some scaling for better visual effect
    const normalizedVolume = Math.min(1, avg / 128) * 1.5
    setVolume(normalizedVolume)

    animationFrameRef.current = requestAnimationFrame(updateVolume)
  }

  // Check if browser supports speech recognition
  if (!browserSupportsSpeechRecognition) {
    toast({
      title: "瀏覽器不支持語音識別",
      description: "請使用支持語音識別的瀏覽器，如 Chrome 或 Firefox。",
      variant: "destructive",
      duration: 5000,
    })
  }

  // Check if microphone is available
  if (!isMicrophoneAvailable) {
    toast({
      title: "麥克風不可用",
      description: "請檢查您的麥克風設置。",
      variant: "destructive",
      duration: 5000,
    })
  }

  return (
    <Dialog open={isOpen}>
      <DialogContent className="sm:max-w-md bg-transparent border-0 shadow-none" closeShow={false}>
        {/* <div className="absolute right-4 top-4">
          <Button variant="ghost" size="icon" onClick={handleClose} className="h-6 w-6">
            <X className="h-4 w-4" />
            <span className="sr-only">關閉</span>
          </Button>
        </div> */}

        <DialogHeader>
          <DialogTitle className="text-center text-white text-2xl"></DialogTitle>
        </DialogHeader>

        <div className="flex flex-col items-center gap-6 py-4">
          <div className="relative flex items-center justify-center w-48 h-48">
            {/* Background circle */}
            <div className="absolute w-36 h-36 bg-gray-100 rounded-full"></div>

            {/* Animated circle that responds to audio */}
            <motion.div
              className="absolute bg-gradient-to-r from-purple-500 to-pink-500 rounded-full"
              style={{
                width: "9rem",
                height: "9rem",
              }}
              animate={{
                scale: 1 + volume * 0.2,
                boxShadow: `0 0 ${10 + volume * 40}px rgba(168, 85, 247, ${0.3 + volume * 0.4})`,
              }}
              transition={{
                type: "spring",
                stiffness: 300,
                damping: 10,
              }}
            />

            {/* Center icon */}
            <div className="relative z-10 text-white">
              <Mic size={32} />
            </div>
          </div>

          <Button onClick={handleClose} className="w-12 h-12 rounded-full bg-white hover:bg-red-600 active:bg-red-700 transition duration-200 ease-in-out text-black hover:text-white">
            <X className="h-12 w-12" />
          </Button>

          <p className="text-sm text-white">正在收聽中...說話後將自動識別</p>
        </div>
      </DialogContent>
    </Dialog>
  )
}