//倒讚的回應表單談窗
import React from 'react';
import { Button } from '@/shadcn-ui/components/ui/button';
import { useTranslation } from 'react-i18next';
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle, DialogDescription } from "@/shadcn-ui/components/ui/dialog";
import { Textarea } from '@/shadcn-ui/components/ui/textarea';
import { Form, FormControl, FormItem, FormField, FormLabel, FormMessage } from '@/shadcn-ui/components/ui/form';
import { useForm } from 'react-hook-form';
import * as yup from "yup";
import { yupResolver } from '@hookform/resolvers/yup';

interface BadFeedbackFormProps extends React.HTMLAttributes<HTMLDivElement> {
  open: boolean
  onOk?: (content: string) => void
  onClose?: () => void
}

export default function BadFeedbackForm({ open, onOk, onClose }: BadFeedbackFormProps) {
  const { t } = useTranslation('chat');
  const { t: commonT } = useTranslation('common');
  const schema = yup.object({
    // type: yup.string().required(),
    content: yup.string().required(t('feedbackPlaceholder')),
  });

  const form = useForm({
    resolver: yupResolver(schema),
    defaultValues: {
      // type: '',
      content: '',
    },
  });

  const { handleSubmit, setValue, reset } = form;

  const onSubmit = (data: { content: string }) => {
    onOk && onOk(data.content);
    reset();
    onClose && onClose();
  }

  const handleClose = () => {
    onClose && onClose();
  }

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="overflow-auto pt-12">
        <DialogHeader>
          <DialogTitle>{t('feedbackTitle')}</DialogTitle>
          <DialogDescription>
            {t('feedbackContent')}
          </DialogDescription>
        </DialogHeader>
        <Form {...form}>
          <form className='px-6' onSubmit={handleSubmit(onSubmit)}>
            <FormItem className="flex flex-col gap-4">
              {/* <FormField
                control={form.control}
                name="type"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>{'您想報告什麼類型的問題?'}</FormLabel>
                    <FormControl>
                      <SingalSelect
                        {...field}
                        className="w-[350px]"
                        placeholder={'請選擇類型'}
                        options={[
                          {
                            label: '沒有完全遵循我的要求',
                            value: '沒有完全遵循我的要求',
                          },
                          {
                            label: '事實不正',
                            value: '事實不正',
                          },
                          {
                            label: '其他',
                            value: '其他',
                          }
                        ]}
                        selected={field.value}
                        onChange={(value) => {
                          field.onChange(value);
                        }}
                      />
                    </FormControl>
                  </FormItem>
                )}
              /> */}
              <FormField
                control={form.control}
                name="content"
                render={({ field }) => (
                  <FormItem className="flex flex-col items-start">
                    <FormLabel className="text-left">{t('feedbackLabel')}</FormLabel>
                    <FormControl>
                      <Textarea rows={4} placeholder={t('feedbackPlaceholder')} {...field} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </FormItem>
          </form>
        </Form>
        <DialogFooter className='mt-6 flex gap-2'>
          <Button className='' variant={'outline'} size={'sm'} onClick={handleClose}>{commonT('cancel')}</Button>
          <Button className='bg-black hover:bg-black/80 mr-0' size={'sm'} onClick={handleSubmit(onSubmit)}>{commonT('submit')}</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}
